# Test refined hypothesis: 2 appears only when horizontally or vertically between CONSECUTIVE 4s (not just any 4s)
def check_rule_refined(input_grid):
    rows, cols = input_grid.shape
    result = np.copy(input_grid)

    for r in range(rows):
        for c in range(cols):
            if input_grid[r, c] == 0:
                # Check horizontal: immediate neighbors are both 4?
                if c > 0 and c < cols-1:
                    if input_grid[r, c-1] == 4 and input_grid[r, c+1] == 4:
                        result[r, c] = 2
                # Check vertical: immediate neighbors are both 4?
                if r > 0 and r < rows-1:
                    if input_grid[r-1, c] == 4 and input_grid[r+1, c] == 4:
                        result[r, c] = 2

    return result

